-- ═══════════════════════════════════════════════════════════════════
-- RAHTIS · документы: цены с 1.10.2026 и стол «напрямую»
--
-- Под поведение 20261001100000: заказчик 5 % со всякого рейса подряда,
-- перевозчик 3 %, вместе не меньше 15 €; стол с выбором — подряд или
-- договор напрямую с перевозчиком-подписчиком без платы.
-- TERMS 8.5 — черновик v18; SHIPPER_AGREEMENT 2.5, 3.4 и CARRIER_AGREEMENT
-- 3.3 — новые черновики. Активация — решение пользователя.
-- ═══════════════════════════════════════════════════════════════════

create or replace function pg_temp.draft_of(p_kind public.legal_kind)
returns uuid
language plpgsql
as $$
declare
  v_active uuid := public.active_legal_document(p_kind);
  v_draft uuid;
begin
  if v_active is null then
    raise exception 'Нет действующей редакции %.', p_kind using errcode = '55007';
  end if;

  select d.id into v_draft
  from public.legal_documents d
  where d.kind = p_kind and d.status = 'DRAFT'
    and d.version > (select version from public.legal_documents where id = v_active)
  order by d.version desc
  limit 1;

  if v_draft is null then
    insert into public.legal_documents (kind, version, status, effective_from)
    values (p_kind, (select max(version) + 1 from public.legal_documents where kind = p_kind),
            'DRAFT', current_date)
    returning id into v_draft;

    insert into public.legal_clauses (document_id, locale, path, title, body)
    select v_draft, c.locale, c.path, c.title, c.body
    from public.legal_clauses c where c.document_id = v_active;
  end if;

  return v_draft;
end;
$$;

create or replace function pg_temp.put(p_doc uuid, p_path integer[], p_fi text, p_en text)
returns void
language sql
as $$
  insert into public.legal_clauses (document_id, locale, path, body)
  values (p_doc, 'fi', p_path, p_fi), (p_doc, 'en', p_path, p_en)
  on conflict (document_id, locale, path) do update set body = excluded.body;
$$;

do $$
declare
  v_terms uuid := pg_temp.draft_of('TERMS');
  v_shipper uuid := pg_temp.draft_of('SHIPPER_AGREEMENT');
  v_carrier uuid := pg_temp.draft_of('CARRIER_AGREEMENT');
begin
  perform pg_temp.put(v_terms, array[8, 5], 'Palvelua voi käyttää kahdella tavalla, ja kuljetusliike valitsee kumpaa se käyttää. Tapaa voi vaihtaa palvelussa, ja vaihto koskee vaihdon jälkeen vahvistettuja keikkoja: jo vahvistettujen ja valmistuneiden keikkojen maksut eivät muutu. Siirtyminen alihankintaan tulee voimaan heti. Paluu kuukausimaksuun tulee voimaan seuraavan kalenterikuukauden alusta, koska alihankintana otettu työ ajetaan loppuun sen ehdoilla. (a) Alusta kuukausimaksulla: maksu on 29,90 euroa kalenterikuukaudessa jokaisesta ajoneuvosta, jolla on kyseisen kuukauden aikana merkitty valmiiksi vähintään yksi keikka; muista palveluun rekisteröidyistä ajoneuvoista ei makseta. Näin ajetaan sekä kuljetusliikkeen omat asiakkaat että palvelussa olevan tilaajan suorat tilaukset silloin, kun tilaaja on lisännyt ajoneuvon omiin autoihinsa. Näistä keikoista ei peritä prosenttiosuutta: kuljetussopimus on kuljetusliikkeen ja sen asiakkaan välinen, eikä Aivomaa Oy laskuta asiakasta, ota vastaan maksuja tai vastaa kuljetuksesta, vaan toimittaa palvelussa raportin tehdystä työstä. Kuukausimaksu vähennetään kuljetusliikkeelle maksettavasta tilityksestä, jos tilitystä on; jos tilitystä ei ole tai se ei riitä, kattamaton osa laskutetaan kuukauden päätyttyä tavanomaisin maksuehdoin. (b) Alihankinta: kuljetusliike toimii Aivomaa Oy:n alihankkijana, jolloin Aivomaa Oy on tilaajan sopimuskumppani, laskuttaa tilaajaa, vastaanottaa rahtikirjat, toimittaa raportit ja käsittelee reklamaatiot. Maksu on 3 prosenttia jokaisen keikan hinnasta, ja se vähennetään kuljetusliikkeelle maksettavasta tilityksestä; kuukausimaksua ajoneuvoista ei tällöin peritä. Kun Aivomaa Oy on tilaajan sopimuskumppani, tilaaja maksaa jokaisesta keikasta 5 prosentin palvelumaksun ja kuljetusliike 3 prosenttia keikan hinnasta; jos maksut yhteensä jäävät alle 15 euron, tilaajan palvelumaksua korotetaan niin, että ne ovat yhteensä 15 euroa. Tarjouspöydälle julkaistessaan tilaaja valitsee, onko Aivomaa Oy sopimuskumppani vai tehdäänkö sopimus suoraan kuljetusliikkeen kanssa. Ensin mainittu keikka ajetaan aina alihankintana riippumatta siitä, kumpaa tapaa kuljetusliike muutoin käyttää. Suoran sopimuksen keikan voi ottaa vain kuukausimaksulla palvelua käyttävä kuljetusliike, ja siihen sovelletaan kohtaa (a): sopimus ja lasku ovat tilaajan ja kuljetusliikkeen välisiä, eikä palvelumaksua tai prosenttiosuutta peritä. Alihankkijana toimivalla kuljetusliikkeellä on oltava voimassa oleva vastuuvakuutus, ja Aivomaa Oy tarkistaa tilaajavastuulain tarkoittamat tiedot ennen sopimusta ja sen jälkeen määräajoin. Keikan valmistumishetkellä voimassa olevat maksut kirjataan kyseiselle keikalle, eivätkä myöhemmät muutokset vaikuta jo valmistuneisiin keikkoihin. Yrityksen hyväksymiskuukauden loppuosa ja sitä seuraava kokonainen kalenterikuukausi ovat maksuttomia; jos yritys hyväksytään kuukauden ensimmäisenä päivänä, maksuton on kyseinen kuukausi. Arvonlisävero määräytyy sopimuskumppanin maan mukaan: suomalaiselle yritykselle lisätään 25,5 prosenttia, muun maan yritykselle sovelletaan käännettyä verovelvollisuutta, jolloin myyjä laskuttaa nollalla ja ostaja tilittää veron omassa maassaan. [Kohta täydennetään juristin kanssa: kuittauksen ehdot, alihankkijan vakuutuksen vähimmäismäärä sekä regressin ehdot.]', 'The service can be used in two ways, and the carrier chooses which one it uses. The way can be changed in the service, and the change applies to jobs confirmed after it: the fees on jobs already confirmed or completed do not change. A move to subcontracting takes effect immediately. A return to the monthly fee takes effect from the beginning of the next calendar month, because work taken as subcontracting is driven to the end on its terms. (a) The platform for a monthly fee: the fee is 29.90 euros per calendar month for each vehicle that has at least one job marked complete during that month; no fee is charged for the other vehicles registered in the service. This covers both the carrier''s own clients and the direct orders of a shipper in the service where the shipper has added the vehicle to its own vehicles. No percentage is charged on these jobs: the contract of carriage is between the carrier and its client, and Aivomaa Oy does not invoice the client, receive payments or bear liability for the transport, but delivers a report of the work done in the service. The monthly fee is deducted from the settlement paid to the carrier where there is one; if there is no settlement or it is not sufficient, the uncovered part is invoiced after the end of the month on the usual payment terms. (b) Subcontracting: the carrier acts as a subcontractor of Aivomaa Oy, in which case Aivomaa Oy is the shipper''s contracting party, invoices the shipper, receives the consignment notes, delivers the reports and handles the claims. The fee is 3 per cent of the price of every job and is deducted from the settlement paid to the carrier; no monthly vehicle fee is charged in that case. Where Aivomaa Oy is the shipper''s contracting party, the shipper pays a service fee of 5 per cent and the carrier 3 per cent of the price of every job; if the fees together are less than 15 euros, the shipper''s service fee is increased so that they total 15 euros. When publishing on the offer table, the shipper chooses whether Aivomaa Oy is the contracting party or the contract is made directly with the carrier. A job of the first kind is always performed as subcontracting regardless of which way the carrier otherwise uses. A direct-contract job can be taken only by a carrier using the service for a monthly fee, and point (a) applies to it: the contract and invoice are between the shipper and the carrier, and no service fee or percentage is charged. A carrier acting as a subcontractor must hold valid liability insurance, and Aivomaa Oy checks the information referred to in the Act on the Contractor''s Obligations before the contract and periodically thereafter. The fees in force at the moment a job is completed are recorded on that job, and later changes do not affect jobs already completed. The remainder of the company''s approval month and the following full calendar month are free of charge; if the company is approved on the first day of a month, that month is free. Value added tax is determined by the country of the contracting party: 25.5 per cent is added for a Finnish company, and the reverse charge applies to a company from another country, whereby the seller invoices at zero and the buyer accounts for the tax in its own country. [This clause is to be completed with counsel: the terms of set-off, the minimum amount of the subcontractor''s insurance and the terms of recourse.]');
  perform pg_temp.put(v_shipper, array[2, 5], 'Tilaaja voi lähettää toimeksiannon suoraan tutulle ajoneuvolle käyttöehtojen kohdan 6.6 mukaisesti. Suora tilaus odottaa vahvistusta ilman määräaikaa, ja sopimus syntyy, kun ajoneuvon kuljetusliike tai kuljettaja vahvistaa sen. Siihen asti tilaaja voi siirtää toimeksiannon tarjouspöydälle. Jos ajoneuvon kuljetusliike käyttää palvelua kuukausimaksulla, suora tilaus tehdään tilaajan ja kyseisen kuljetusliikkeen välillä: kuljetusliike näkyy tilaajalle nimeltä, laskuttaa tilaajaa itse ja vastaa kuljetuksesta, ja Aivomaa Oy välittää tiedot sekä raportin tehdystä työstä. Muissa tapauksissa Aivomaa Oy on tilaajan sopimuskumppani myös suorissa tilauksissa. Palvelumaksu määräytyy kohdan 3.4 mukaan.', 'The shipper may send an assignment directly to a known vehicle in accordance with clause 6.6 of the terms of use. A direct order waits for confirmation without a deadline, and the contract is formed when the vehicle''s carrier or driver confirms it. Until then the shipper may move the assignment to the offer table. If the vehicle''s carrier uses the service for a monthly fee, the direct order is made between the shipper and that carrier: the carrier is shown to the shipper by name, invoices the shipper itself and is liable for the transport, while Aivomaa Oy passes on the data and a report of the work done. In other cases Aivomaa Oy is the shipper''s contracting party also in direct orders. The service fee is determined under clause 3.4.');
  perform pg_temp.put(v_shipper, array[3, 4], 'Kun Aivomaa Oy on tilaajan sopimuskumppani, Aivomaa Oy lisää laskuun palvelumaksun, joka on 5 prosenttia valmistuneen kuljetuksen hinnasta, sekä yhteisen pöydän kautta että suorassa tilauksessa. Jos palvelumaksu ja kuljetusliikkeen Aivomaa Oy:lle maksama 3 prosentin maksu jäävät yhteensä alle 15 euron, palvelumaksua korotetaan niin, että ne ovat yhteensä 15 euroa. Palvelumaksua ei peritä, kun sopimus on tehty suoraan kuukausimaksulla palvelua käyttävän kuljetusliikkeen kanssa (suora tilaus tällaisen kuljetusliikkeen ajoneuvolle tai tarjouspöydän tilaus, jonka tilaaja on julkaissut suoran sopimuksen tilauksena), eikä peruutetusta tilauksesta. Odotusaikalisästä ei peritä palvelumaksua. Hyväksymiskuukauden loppuosa ja sitä seuraava kokonainen kalenterikuukausi ovat maksuttomia käyttöehtojen kohdan 8.5 mukaisesti.', 'Where Aivomaa Oy is the shipper''s contracting party, Aivomaa Oy adds to the invoice a service fee of 5 per cent of the price of a completed transport, both through the offer table and in a direct order. If the service fee and the 3 per cent fee paid by the carrier to Aivomaa Oy together are less than 15 euros, the service fee is increased so that they total 15 euros. No service fee is charged where the contract is made directly with a carrier using the service for a monthly fee (a direct order to such a carrier''s vehicle, or an offer-table order published by the shipper as a direct-contract order), or for a cancelled order. No service fee is charged on the waiting surcharge. The remainder of the month of approval and the following full calendar month are free of charge under clause 8.5 of the terms of use.');
  perform pg_temp.put(v_carrier, array[3, 3], 'Itsenäisellä kuljetusliikkeellä on pääsy keikkalistalle. Keikkalistalta vastaanotettuun toimeksiantoon, jossa Aivomaa Oy on tilaajan sopimuskumppani, sovelletaan kohdan 2.4 mukaisesti Alihankkija-mallin ehtoja ja 3 prosentin palvelumaksua toimeksiannon kuljetushinnasta; kuukausimaksu ei poista tätä palvelumaksua. Jos tilaaja on julkaissut toimeksiannon suoran sopimuksen tilauksena, sen voi ottaa vain itsenäinen kuljetusliike: kuljetussopimus syntyy kuljetusliikkeen ja tilaajan välille, kuljetusliike laskuttaa tilaajaa itse, eikä palvelumaksua peritä.', 'An independent carrier has access to the job list. An assignment taken from the job list where Aivomaa Oy is the shipper''s contracting party is subject, under section 2.4, to the terms of the Subcontractor model and to a service fee of 3 per cent of its freight price; the monthly fee does not remove this service fee. If the shipper has published the assignment as a direct-contract order, only an independent carrier can take it: the contract of carriage is formed between the carrier and the shipper, the carrier invoices the shipper itself, and no service fee is charged.');
end;
$$;
